<script lang="ts">
 import {landingCopy,type LandingLocale} from './landing-copy';
 type Method='web'|'cli'|'mcp';
 let {onlogin,onpublic,connected=false,onreturn,locale='en'}:{onlogin:()=>void;onpublic:()=>void;connected?:boolean;onreturn:()=>void;locale?:LandingLocale}=$props();
 const t=$derived(landingCopy[locale].agentSetup);
 const methods=$derived(t.methods);
 let selected=$state<Method>('web');
 let message=$state<'mcp'|'commands'|'manual'|''>('');
 const localCommand='git clone https://github.com/heycodingkr/my-document-memory.git\ncd my-document-memory\nnode scripts/dev.mjs';
 const cliCommand='cargo install --path crates/dmem-cli --locked --debug\nset -a\n. ./.env\nset +a\nexport DMEM_URL=http://127.0.0.1:3847\ndmem status\ndmem templates Meeting';

 const mcpConfig=JSON.stringify({mcpServers:{'document-memory':{command:'/absolute/path/to/dmem-mcp',env:{DMEM_URL:'http://127.0.0.1:3847',DMEM_TOKEN:'<your library token>'}}}},null,2);
 const copyValue=$derived(selected==='web'?localCommand:selected==='cli'?cliCommand:mcpConfig);
 function choose(id:Method){selected=id;message='';}
 function key(event:KeyboardEvent,index:number){let next=index;if(event.key==='ArrowRight')next=(index+1)%methods.length;else if(event.key==='ArrowLeft')next=(index+methods.length-1)%methods.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=methods.length-1;else return;event.preventDefault();choose(methods[next].id);document.getElementById('connection-tab-'+methods[next].id)?.focus();}
 async function copy(){try{await navigator.clipboard.writeText(copyValue);message=selected==='mcp'?'mcp':'commands';}catch{message='manual';}}
</script>
<section class="agent-setup" id="connect-agent" aria-labelledby="agent-setup-title">
 <div class="setup-heading"><div><span class="kicker">{t.kicker}</span><h2 id="agent-setup-title">{t.title}<br/>{t.titleNext}</h2></div><p>{t.summary}<br/>{t.summaryNext}</p></div>
 <div class="connection-methods" role="tablist" aria-label={t.tabsAria}>{#each methods as method,i}<button role="tab" aria-label={method.name} id={'connection-tab-'+method.id} aria-controls="connection-panel" aria-selected={selected===method.id} tabindex={selected===method.id?0:-1} class:selected={selected===method.id} onclick={()=>choose(method.id)} onkeydown={(event)=>key(event,i)}><strong>{method.name}</strong><span>{method.detail}</span></button>{/each}</div>
 <div class="connection-panel" id="connection-panel" role="tabpanel" aria-labelledby={'connection-tab-'+selected} tabindex="0">
  <div class="method-description">
   {#if selected==='web'}<span class="method-number">{t.web.index}</span><h3>{t.web.title}</h3><p>{t.web.description}</p><div class="method-actions"><button class="method-primary" onclick={connected?onreturn:onlogin}>{connected?t.web.open:t.web.create} →</button><button class="method-link" onclick={onpublic}>{t.web.public} →</button></div><p class="method-note">{t.web.note}</p>
   {:else if selected==='cli'}<span class="method-number">{t.cli.index}</span><h3>{t.cli.title}</h3><p>{t.cli.description}</p><p class="method-note">{t.cli.note} <code>node scripts/dev.mjs</code>. Your local <code>.env</code> supplies the connection token.</p><a class="method-link" href="https://github.com/heycodingkr/my-document-memory#cli" target="_blank" rel="noreferrer noopener">{t.cli.guide} ↗</a>
   {:else}<span class="method-number">{t.mcp.index}</span><h3>{t.mcp.title}</h3><p>{t.mcp.description}</p><p class="method-note">{t.mcp.note}</p><a class="method-link" href="https://github.com/heycodingkr/my-document-memory#stdio-mcp" target="_blank" rel="noreferrer noopener">{t.mcp.guide} ↗</a>{/if}
  </div>
  <div class="method-code"><div class="code-heading"><span>{selected==='mcp'?t.codeHeading.mcp:selected==='cli'?t.codeHeading.cli:t.codeHeading.web}</span><button onclick={copy} aria-label={selected==='mcp'?t.copy.mcpButton:t.copy.setupButton}>{t.copy.button} <span aria-hidden="true">⧉</span></button></div><pre aria-label={selected==='mcp'?(locale==='en'?'MCP configuration':'MCP 설정'):selected==='cli'?(locale==='en'?'CLI commands':'CLI 명령'):t.codeHeading.web}><code>{copyValue}</code></pre>{#if message}<p class="setup-copy-status" role="status">{message==='mcp'?t.copy.mcpSuccess:message==='commands'?t.copy.commandsSuccess:t.copy.fallback}</p>{/if}</div>
 </div>
 {#each t.protocolNotes as note}<p class="protocol-note">{note}</p>{/each}
</section>
<style>
 .agent-setup{scroll-margin-top:25px;padding-block:60px 45px}.kicker{font-size:10px;font-weight:650;letter-spacing:.13em;color:#6c7d64;line-height:1.7}.setup-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;margin-bottom:30px}.setup-heading h2{font-size:36px;font-weight:500;line-height:1.35;letter-spacing:-.05em;margin:12px 0 0}.setup-heading>p{font-size:13px;color:#64756b;line-height:1.8;margin:0 0 4px}.connection-methods{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid #dce3d8;border-radius:8px 8px 0 0;overflow:hidden;background:#f0f4e9}.connection-methods button{border:0;border-right:1px solid #dce3d8;border-bottom:3px solid transparent;background:transparent;padding:20px 24px;text-align:left;color:#687b5c}.connection-methods button:last-child{border-right:0}.connection-methods button.selected{border-bottom-color:#284f3c;background:#fffef9;color:#284f3c}.connection-methods strong{display:block;font-size:17px;font-weight:600}.connection-methods span{display:block;font-size:11px;margin-top:5px}.connection-panel{display:grid;grid-template-columns:1fr 1fr;gap:45px;padding:36px;background:#fffef9;border:1px solid #dce3d8;border-top:0;border-radius:0 0 8px 8px;min-width:0}.method-description{min-width:0}.method-number{font-size:9px;letter-spacing:.1em;color:#7b8c6b}.method-description h3{font-size:25px;line-height:1.4;font-weight:500;letter-spacing:-.04em;margin:14px 0}.method-description p{font-size:13px;line-height:1.9;color:#64756b}.method-description p.method-note{font-size:11px;margin-top:22px}.method-description code{font-size:10px;overflow-wrap:anywhere}.method-actions{display:flex;flex-wrap:wrap;gap:15px;align-items:center;margin-top:22px}.method-primary{padding:12px 17px;background:#284f3c;color:white;border-radius:5px;border:1px solid #284f3c;font-size:12px}.method-link{font-size:11px;line-height:1.7;border:0;background:transparent;color:#456d45;padding:0}.method-code{min-width:0;background:#eef3e7;border:1px solid #dce4d2;border-radius:6px;align-self:start;overflow:hidden}.code-heading{display:flex;justify-content:space-between;align-items:center;gap:14px;border-bottom:1px solid #dce4d2;padding:13px 16px;font-size:10px;color:#667b57}.code-heading button{display:flex;gap:14px;padding:5px 7px;border:0;background:transparent;color:#37583e;font-size:11px}.method-code pre{font:11px/1.9 ui-monospace,SFMono-Regular,monospace;padding:18px;margin:0;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;user-select:text;color:#3d573e}.setup-copy-status{font-size:11px;color:#3f663c;padding:0 18px 12px;margin:0;line-height:1.8}.protocol-note{font-size:11px;line-height:1.9;color:#738167;margin:18px 0 0}button:focus-visible,a:focus-visible{outline:2px solid #5c7c4d;outline-offset:4px}
 @media(max-width:850px){.connection-panel{gap:25px;padding:27px}.setup-heading h2{font-size:30px}.setup-heading>p{font-size:11px}.method-description h3{font-size:22px}.method-actions{display:block}.method-actions>.method-link{margin-top:14px;display:block}}
 @media(max-width:580px){.agent-setup{padding-block:38px 26px}.setup-heading{display:block;margin-bottom:22px}.setup-heading h2{font-size:28px}.setup-heading>p{margin-top:15px;font-size:12px}.setup-heading>p br{display:none}.connection-methods button{padding:15px 10px}.connection-methods strong{font-size:14px}.connection-methods span{font-size:9px;line-height:1.6}.connection-panel{grid-template-columns:1fr;padding:23px 18px;gap:22px}.method-description h3{font-size:24px}.method-description p{font-size:13px}.method-code pre{padding:16px;font-size:10px}.code-heading{padding:11px 13px;font-size:9px}.protocol-note{font-size:10px}}
</style>
